/*
 * A169452  Number of reduced words of length n in Coxeter group on 7
 *          generators S_i with relations (S_i)^2 = (S_i S_j)^33 = I.
 * https://oeis.org/A169452
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn, easy
 * Formula:   not stated
 * Range:     u8 n <= 3, u16 n <= 6, u32 n <= 12, u64 n <= 24, u128 n <= 49,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* Sequence A169452: number of reduced words of length n in the Coxeter group
 * generated by 7 involutions with (S_i S_j)^3 = 1.
 *
 * We compute the auxiliary sequence b_n defined by
 *
 *    b_0 = 1,
 *    b_n = 6*b_{n-1} - 20*b_{n-33} + 15*b_{n-34}   (n ≥ 1, indices < 0 are 0)
 *
 * Then the required values are
 *
 *    a(n) = b_n + b_{n-1} - b_{n-33} - b_{n-34}    (indices < 0 are 0).
 *
 * This is equivalent to the recurrence
 *
 *    a(n) = -15*a(n-33) + 5*∑_{k=1}^{32} a(n-k)   (n ≥ 33)
 *
 * with initial values a(0)=1, a(1)=7, a(2)=42, …  (first 33 terms are
 * generated automatically via the above formulas).  The implementation
 * memoises the b sequence so that calls with arbitrary ordering are
 * answered in O(n) time for the largest requested n.
 */

#include <stdlib.h>

seq_t a(idx_t n)
{
    /* Static state to retain computed b_n values between calls. */
    static seq_t *b_arr = NULL;      /* array of b_n */
    static size_t  b_cap = 0;        /* current capacity of array */
    static idx_t   b_len = 0;        /* number of b values already computed
                                       (next index to compute) */

    /* Ensure the array is large enough.  For a value of n, we need b up to
       index n (and possibly a few earlier indices, which are already
       computed by the recurrence).  Start with a small capacity if needed. */
    if (!b_arr) {
        b_cap = 64;
        b_arr = (seq_t *)malloc(b_cap * sizeof(seq_t));
        /* initialise b_0 = 1 */
        b_arr[0] = 1;
        b_len = 1;
    }
    while (b_len <= n) {
        /* grow array if necessary */
        if ((size_t)b_len >= b_cap) {
            size_t new_cap = b_cap * 2;
            seq_t *tmp = (seq_t *)realloc(b_arr, new_cap * sizeof(seq_t));
            if (!tmp) abort();  /* allocation failure */
            b_arr = tmp;
            b_cap = new_cap;
        }
        idx_t i = b_len;
        seq_t val = b_arr[i-1] * (seq_t)6;
        if (i >= 33) val -= b_arr[i-33] * (seq_t)20;
        if (i >= 34) val += b_arr[i-34] * (seq_t)15;
        b_arr[b_len++] = val;
    }

    /* Calculate a(n) from the already computed b array.  Indices < 0 are
       treated as 0 by the nature of the auxiliary sequence definition. */
    seq_t result = b_arr[n];
    if (n >= 1) result += b_arr[n-1];
    if (n >= 33) result -= b_arr[n-33];
    if (n >= 34) result -= b_arr[n-34];
    return result;
}
